-- 2026-11-02 책나무 영상 교육자료 리스트 반영 (phpMyAdmin > SQL 에서 실행)
SET NAMES utf8mb4;
-- 1) lessons 테이블 컬럼 추가 (이미 추가돼 있으면 이 4줄은 오류가 나므로 건너뛰세요)
ALTER TABLE `lessons` ADD COLUMN `ref_no` VARCHAR(20) NULL COMMENT '본사 자료실(bbs) 글 번호' AFTER `description`;
ALTER TABLE `lessons` ADD COLUMN `lecturer` VARCHAR(100) NULL AFTER `ref_no`;
ALTER TABLE `lessons` ADD COLUMN `lecture_date` DATE NULL AFTER `lecturer`;
ALTER TABLE `lessons` ADD COLUMN `is_required` TINYINT NOT NULL DEFAULT 0 COMMENT '1=신규 원장 필수 시청(★)' AFTER `lecture_date`;

-- 2) 데모 과정 비공개
UPDATE `courses` SET `is_active` = 0 WHERE `title` IN ('신규원장교육', '지점SW 사용교육', '보수교육');

-- 3) 분류 → 교육과정

-- 4) 강의 45건 (자료실 번호가 이미 있으면 건너뜀). 영상 주소는 관리자 > 교육과정 > '본사 자료실에서 영상 주소 가져오기' 로 채웁니다.
